"use client";

import { useEffect, useMemo, useState } from "react";
import { copyText, runMicrotask, storageGet, storageRemove, storageSet } from "./client-compat";
import { translations, type Language, type Translation } from "./bilingual-i18n";
import { localeCopy } from "./bilingual-locale-copy";
import { uiCopy } from "./bilingual-ui-copy";
import { ProjectAnnouncement } from "./project-announcement";

type TaskRow={id:string;title_zh:string;title_en:string;body:string|null;submission_status:string|null;updated_at:number|null;status:string;week:number};
type GroupRow={id:string;name:string;member_count:number;created_at:number;can_manage?:boolean;default_channel_id?:string|null;default_channel_name?:string|null};
type ChannelRow={id:string;group_id:string;name:string;kind:string;position:number};
type MemberRow={id:string;display_code:string;last_active_at:number|null;activity_count:number};
type MessageRow={id:string;body:string;display_code:string;created_at:number;edited_at:number|null;participant_id:string;channel_id:string};
type ParticipantRow={id:string;display_code:string};
type FileRow={id:string;name:string;content_type:string;size:number;created_at:number;participant_id:string};
type GameLinkRow={id:string;version:string;url:string;notes_zh:string|null;notes_en:string|null;published_at:number};
type JournalRow={id:string;title_zh:string;title_en:string;body_zh:string;body_en:string;stage:string;tags:string;participant_id:string|null;content_type:string|null;file_name:string|null;occurred_at:number};
type SurveyFormRow={id:string;title_zh:string;title_en:string;question_zh:string;question_en:string;status?:string;created_at?:number};
type Discipline="planning"|"art"|"programming";
type DesignerRow={id:string;name:string;role:string;discipline:Discipline|"";division:string;bio:string;profile_link:string;contribution:number;sort_order:number;updated_at:number};

function shortError(lang:Language){return lang==="zh"?"暂时无法完成操作，请稍后重试。":"This action is temporarily unavailable. Please try again."}
function beijingGreeting(lang:Language){const hour=Number(new Intl.DateTimeFormat("en-GB",{timeZone:"Asia/Shanghai",hour:"2-digit",hourCycle:"h23"}).format(new Date()));if(lang==="zh")return hour<12?"早上好":hour<18?"下午好":"晚上好";if(lang==="en")return hour<12?"Good morning":hour<18?"Good afternoon":"Good evening";return "Hello"}

export function PublicDesignerRanking({lang}:{lang:Language}){
 const c=localeCopy[lang];const pending=lang==="zh"?"待录入":"To be added";
 return <section className="publicCredits publicCreditsPending" id="designers"><div className="creditsHead"><span className="kicker">{c.collaborators}</span><h2>{c.collaborators}</h2><p>{lang==="zh"?"共同创作者名单将在人员信息确认后统一录入。":"The collaborator list will be added after participant information is confirmed."}</p></div><div className="collaboratorPending" role="status"><span>01—100</span><b>{pending}</b></div></section>
}

export function DesignerRosterManager({lang}:{lang:Language}){
 const zh=lang==="zh";const [rows,setRows]=useState<DesignerRow[]>([]);const [search,setSearch]=useState("");const [selected,setSelected]=useState("");const [name,setName]=useState("");const [role,setRole]=useState("");const [discipline,setDiscipline]=useState<Discipline|"">("");const [division,setDivision]=useState("");const [bio,setBio]=useState("");const [profileLink,setProfileLink]=useState("");const [score,setScore]=useState("0");const [status,setStatus]=useState("");
 const load=()=>fetch("/api/designers",{cache:"no-store"}).then(r=>r.json()).then(d=>{setRows(d.designers||[]);setSelected((x:string)=>x||d.designers?.[0]?.id||"")});
 useEffect(()=>{load().catch(()=>undefined)},[]);
 useEffect(()=>{const row=rows.find(x=>x.id===selected);if(row)runMicrotask(()=>{setName(row.name);setRole(row.role);setDiscipline(row.discipline||"");setDivision(row.division||"");setBio(row.bio||"");setProfileLink(row.profile_link||"");setScore(String(row.contribution))})},[selected,rows]);
 async function save(){const r=await fetch("/api/designers",{method:"PATCH",headers:{"content-type":"application/json"},body:JSON.stringify({id:selected,name,role,discipline,division,bio,profileLink,contribution:Number(score)})});if(r.ok){setStatus(zh?"名片与分工已更新。":"Profile card updated.");await load()}else{const data=await r.json().catch(()=>({}));setStatus(data.error||(zh?"更新失败。":"Update failed."))}}
 const filtered=rows.filter(x=>x.name.toLowerCase().includes(search.toLowerCase()));
 return <section className="rosterManager"><div className="contentEditorHead"><div><span className="kicker">PUBLIC PEOPLE</span><h2>{zh?"共同创作者名片管理":"Collaborator profile cards"}</h2><p>{zh?"每位设计师都可以拥有姓名、角色、分工标签、具体职责、简介和个人链接。":"Each designer can have a name, role, discipline, responsibilities, biography, and profile link."}</p></div></div><div className="rosterSelect"><input value={search} onChange={e=>setSearch(e.target.value)} placeholder={zh?"搜索设计师":"Search designers"}/><select value={selected} onChange={e=>setSelected(e.target.value)}>{filtered.map(x=><option key={x.id} value={x.id}>{x.name}</option>)}</select></div><div className="profileEditorGrid"><label>{zh?"姓名":"Name"}<input value={name} onChange={e=>setName(e.target.value)}/></label><label>{zh?"角色 / 职位":"Role / title"}<input value={role} onChange={e=>setRole(e.target.value)}/></label><label>{zh?"分工标签":"Discipline"}<select value={discipline} onChange={e=>setDiscipline(e.target.value as Discipline|"")}><option value="">{zh?"暂未分类":"Unassigned"}</option><option value="planning">{zh?"策划":"Planning"}</option><option value="art">{zh?"美术":"Art"}</option><option value="programming">{zh?"编程":"Programming"}</option></select></label><label>{zh?"内部贡献分":"Internal contribution score"}<input type="number" value={score} onChange={e=>setScore(e.target.value)}/></label><label className="wide">{zh?"具体分工（用逗号分隔）":"Responsibilities (comma separated)"}<input value={division} onChange={e=>setDivision(e.target.value)} placeholder={zh?"例如：项目构想、艺术方向、参与者协作":"e.g. Concept, art direction, coordination"}/></label><label className="wide">{zh?"名片简介":"Profile biography"}<textarea value={bio} onChange={e=>setBio(e.target.value)} placeholder={zh?"简要说明这位设计师在项目中的工作":"Describe this designer's work in the project"}/></label><label className="wide">{zh?"个人链接（可选）":"Profile link (optional)"}<input type="url" value={profileLink} onChange={e=>setProfileLink(e.target.value)} placeholder="https://"/></label></div><button className="dark profileSave" onClick={save}>{zh?"保存名片":"Save profile card"}</button>{status&&<p className="saveStatus" role="status">{status}</p>}</section>
}

export function LiveTasks({t,lang,onOpenSurvey}:{t:Translation;lang:Language;onOpenSurvey?:()=>void}){
 const u=uiCopy[lang];const [tasks,setTasks]=useState<TaskRow[]>([]);const [selected,setSelected]=useState("");const [week,setWeek]=useState(0);const [text,setText]=useState("");const [status,setStatus]=useState("");const [saving,setSaving]=useState(false);const [loaded,setLoaded]=useState(false);
 useEffect(()=>{fetch("/api/tasks",{cache:"no-store"}).then(async r=>{if(!r.ok)throw new Error();const data=await r.json() as {tasks:TaskRow[]};const rows=data.tasks||[];setTasks(rows);const firstWeek=rows[0]?.week??0;setWeek(firstWeek);setSelected(rows.find(x=>x.week===firstWeek)?.id||"")}).catch(()=>setStatus("暂时无法读取任务 / Unable to load tasks.")).finally(()=>setLoaded(true))},[]);
 const task=tasks.find(x=>x.id===selected);
 useEffect(()=>{if(!task)return;const local=storageGet(`w100-draft-${task.id}`);runMicrotask(()=>{setText(task.body??local??"");setStatus("")})},[task]);
 async function save(submit=false){if(!task)return;setSaving(true);storageSet(`w100-draft-${task.id}`,text);const res=await fetch("/api/tasks",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({taskId:task.id,body:text,status:submit?"submitted":"draft"})}).catch(()=>null);setSaving(false);if(res?.ok){storageRemove(`w100-draft-${task.id}`);setStatus(t.tasks.saved)}else setStatus(shortError(lang))}
 if(!loaded)return <div className="page narrow"><div className="kicker">{t.nav.tasks}</div><h1>{t.nav.tasks}</h1><div className="workspaceLoading" aria-label={lang==="zh"?"正在读取任务":"Loading tasks"}/></div>;
 if(!tasks.length)return <div className="page narrow"><div className="kicker">{t.nav.tasks}</div><h1>{t.nav.tasks}</h1><div className="lock">{status||(lang==="zh"?"暂无已发布任务。":"No tasks have been published.")}</div></div>;
 const taskTitle=(x:TaskRow)=>x.id==="week0-digital-proposal"&&lang==="zh"
  ?"Digital Proposal / 电子提案（可选）"
  :lang==="zh"?x.title_zh:lang==="en"?x.title_en:t.tasks.title;
 const weekTasks=tasks.filter(x=>x.week===week);
 const ownerPending=task?.id==="week0-top-five-games";
 const participantSurvey=task?.id==="week0-participant-survey"
  ||Boolean(task?.title_zh.includes("参与者信息问卷"))
  ||Boolean(task?.title_en.toLowerCase().includes("participant survey"));
 const digitalProposal=task?.id==="week0-digital-proposal";
 const promptLabel=digitalProposal?(lang==="zh"?"提案说明（可选）":"Proposal note (optional)"):t.tasks.prompt;
 const promptPlaceholder=digitalProposal?(lang==="zh"?"可简要写下核心概念、游戏机制、叙事、视觉方向或希望讨论的问题；也可以直接上传提案文件。":"Briefly note the concept, mechanics, narrative, visual direction, or questions for discussion. You can also upload the proposal file directly."):t.tasks.placeholder;
 return <div className="page narrow"><div className="kicker">{t.nav.tasks}</div><div className="weekTabs" aria-label={lang==="zh"?"任务周次":"Task week"}>{[0,1,2,3,4].map(n=><button key={n} className={week===n?"active":""} onClick={()=>{setWeek(n);setSelected(tasks.find(x=>x.week===n)?.id||"")}}>Week {n}<small>{tasks.filter(x=>x.week===n).length}</small></button>)}</div>{task&&weekTasks.length?<><h1>{taskTitle(task)}</h1>{weekTasks.length>1&&<div className="groupTabs">{weekTasks.map(x=><button key={x.id} className={x.id===selected?"active":""} onClick={()=>setSelected(x.id)}>{taskTitle(x)}</button>)}</div>}{ownerPending?<section className="taskOwnerPending" role="status"><span>{lang==="zh"?"已在微信群完成收集":"COLLECTED IN WECHAT"}</span><strong>{lang==="zh"?"这里不需要再次填写":"No further submission is needed here"}</strong><p>{lang==="zh"?"请等待主策划 Hera 整理并上传至网站。":"Please wait while Lead Designer Hera organises the responses and uploads them to the site."}</p></section>:participantSurvey?<section className="creatorTaskAction"><p>{lang==="zh"?"问卷用于了解每位参与者的经验、创作判断、媒介偏好、合作意向与参与方式。草稿会自动保存在当前设备上。":"This survey records each participant's experience, creative judgment, media preferences, collaboration interests, and way of participating. Drafts are saved on this device."}</p><a className="primary" href="/workspace?view=survey" onClick={event=>{if(!onOpenSurvey)return;event.preventDefault();onOpenSurvey()}}>{lang==="zh"?"进入参与者创作画像问卷":"Open the Participant Creative Portrait"}</a></section>:<><p className="creatorTaskNote">{digitalProposal?(lang==="zh"?"这项任务为自愿提交。已有较完整想法时，可参考群公告整理提案；没有完整想法时不必临时构思。提案也可以私发主策划 Hera，或发到群里讨论。":"This is optional. If your idea is already developed, use the group notice as a proposal guide. There is no need to invent an idea for submission. You may also send it privately to Lead Designer Hera or discuss it in the group."):(lang==="zh"?"任务可以分次完成。未完成的内容先保存为草稿，确认后再提交。":"Tasks can be completed in stages. Save unfinished work as a draft and submit it when ready.")}</p><div className="prompt"><span>{promptLabel}</span><textarea value={text} onChange={e=>{setText(e.target.value);storageSet(`w100-draft-${task.id}`,e.target.value)}} onBlur={()=>text.trim()&&save(false)} placeholder={promptPlaceholder}/><div><small>{text.length} · {saving?u.save:status||t.tasks.auto}</small><button className="primary" onClick={()=>save(true)} disabled={saving||!text.trim()}>{digitalProposal?(lang==="zh"?"保存提案说明":"Save proposal note"):t.tasks.save}</button></div></div><LiveUpload t={t} lang={lang} taskId={task.id}/></>}</>:<div className="weekEmpty"><b>Week {week}</b><p>{lang==="zh"?"本周暂无任务。发布后会显示在这里。":"No tasks have been published for this week."}</p></div>}</div>
}

export function LiveSurvey({t,lang}:{t:Translation;lang:Language}){
 const u=uiCopy[lang];const [form,setForm]=useState<SurveyFormRow|null>(null);const [scale,setScale]=useState(0);const [moment,setMoment]=useState("");const [status,setStatus]=useState("");const [saving,setSaving]=useState(false);const [loaded,setLoaded]=useState(false);
 useEffect(()=>{fetch("/api/surveys",{cache:"no-store"}).then(async r=>{if(!r.ok)return;const data=await r.json() as {form?:SurveyFormRow|null;response?:{scale?:number;moment?:string}};setForm(data.form||null);setScale(data.response?.scale||0);setMoment(data.response?.moment||"");setLoaded(true)}).catch(()=>setLoaded(true))},[]);
 async function submit(){if(!form)return;setSaving(true);const res=await fetch("/api/surveys",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({surveyId:form.id,scale,moment})}).catch(()=>null);setSaving(false);setStatus(res?.ok?t.tasks.saved:shortError(lang))}
 if(loaded&&!form)return <div className="page narrow"><div className="kicker">{t.nav.survey}</div><h1>{t.nav.survey}</h1><div className="lock">{t.survey.moment}</div></div>;
 return <div className="page narrow"><div className="kicker">{t.nav.survey}</div><h1>{form?(lang==="zh"?form.title_zh:lang==="en"?form.title_en:t.survey.title):t.survey.title}</h1><fieldset className="scale"><legend>{t.survey.scale}</legend>{[1,2,3,4,5].map(n=><label key={n}><input type="radio" name="scale" checked={scale===n} onChange={()=>setScale(n)}/><span>{n}</span></label>)}</fieldset><label className="field">{form?(lang==="zh"?form.question_zh:lang==="en"?form.question_en:t.survey.moment):t.survey.moment}<textarea value={moment} onChange={e=>setMoment(e.target.value)}/></label><button className="primary" onClick={submit} disabled={saving||!scale||!form}>{saving?u.save:t.survey.submit}</button>{status&&<p className="saveStatus" role="status">{status}</p>}</div>
}

export function LiveUpload({t,lang,taskId,groupId,category,week,onUploaded}:{t:Translation;lang:Language;taskId?:string;groupId?:string;category?:"draft"|"process"|"final";week?:number;onUploaded?:()=>void}){
 const u=uiCopy[lang];const [status,setStatus]=useState("");const [busy,setBusy]=useState(false);
 async function upload(files:FileList|null){if(!files?.length)return;setBusy(true);let completed=0;for(const file of Array.from(files)){const form=new FormData();form.set("file",file);if(taskId)form.set("taskId",taskId);if(groupId)form.set("groupId",groupId);if(category)form.set("category",category);if(week!==undefined)form.set("week",String(week));const res=await fetch("/api/uploads",{method:"POST",body:form}).catch(()=>null);if(res?.ok)completed++}setBusy(false);setStatus(completed===files.length?(lang==="zh"?`✓ ${completed} 个文件已保存`:`✓ ${completed} file${completed===1?"":"s"} saved`):(lang==="zh"?`已保存 ${completed}/${files.length} 个文件，请重试其余文件`:`${completed}/${files.length} files saved — retry the rest`));if(completed)onUploaded?.()}
 return <label className={`upload ${busy?"busy":""}`}><input type="file" multiple accept="image/jpeg,image/png,image/webp,image/heic,image/heif,audio/mpeg,audio/wav,audio/mp4,video/mp4,application/pdf,text/plain,.docx,.xlsx,.pptx" onChange={e=>upload(e.target.files)}/><span>＋</span><b>{busy?u.uploading:t.upload.add}</b><small>{status||t.upload.detail}</small></label>
}

export function LiveGroups({t,lang,active=true}:{t:Translation;lang:Language;active?:boolean}){
 const u=uiCopy[lang];const [groups,setGroups]=useState<GroupRow[]>([]);const [groupsLoaded,setGroupsLoaded]=useState(false);const [groupDataReady,setGroupDataReady]=useState(false);const [messagesReady,setMessagesReady]=useState(false);const [groupId,setGroupId]=useState("");const [channels,setChannels]=useState<ChannelRow[]>([]);const [channelId,setChannelId]=useState("");const [members,setMembers]=useState<MemberRow[]>([]);const [messages,setMessages]=useState<MessageRow[]>([]);const [files,setFiles]=useState<FileRow[]>([]);const [draft,setDraft]=useState("");const [error,setError]=useState("");const [newChannel,setNewChannel]=useState("");const [editing,setEditing]=useState("");const [editText,setEditText]=useState("");const [me,setMe]=useState("");const [showFiles,setShowFiles]=useState(false);const [loadingGroup,setLoadingGroup]=useState(false);const [now]=useState(()=>Date.now());const [canManage,setCanManage]=useState(false);const [canCreate,setCanCreate]=useState(false);const [allParticipants,setAllParticipants]=useState<ParticipantRow[]>([]);const [showGroupForm,setShowGroupForm]=useState(false);const [groupName,setGroupName]=useState("");const [selectedMembers,setSelectedMembers]=useState<string[]>([]);const [groupFormMode,setGroupFormMode]=useState<"create"|"settings">("create");
 const loadGroups=()=>fetch("/api/groups",{cache:"no-store"}).then(async r=>{if(!r.ok)throw new Error();const data=await r.json() as {groups:GroupRow[];canManage?:boolean;canCreate?:boolean};const nextGroups=data.groups||[];setGroups(nextGroups);setCanManage(Boolean(data.canManage));setCanCreate(Boolean(data.canCreate));const selected=nextGroups.find(g=>g.id===groupId)||nextGroups[0];setGroupId(selected?.id||"");if(selected)await loadGroup(selected.id,selected.default_channel_id||"");if(data.canManage)fetch("/api/contributions",{cache:"no-store"}).then(r=>r.json()).then(d=>setAllParticipants(d.participants||[])).catch(()=>undefined)}).catch(()=>setError(t.groups.lock)).finally(()=>setGroupsLoaded(true));
 const loadGroup=(id:string,preferredChannelId="")=>{setGroupDataReady(false);setMessagesReady(false);setMessages([]);setShowFiles(false);setLoadingGroup(true);const channelsRequest=fetch(`/api/channels?groupId=${encodeURIComponent(id)}`,{cache:"no-store"}).then(r=>r.json());const membersRequest=fetch(`/api/group-members?groupId=${encodeURIComponent(id)}`,{cache:"no-store"}).then(r=>r.json());const messagesRequest=preferredChannelId?fetch(`/api/messages?groupId=${encodeURIComponent(id)}&channelId=${encodeURIComponent(preferredChannelId)}`,{cache:"no-store"}).then(r=>r.json()):Promise.resolve({messages:[]});return Promise.all([channelsRequest,membersRequest,messagesRequest]).then(async([a,b,c])=>{const nextChannels=a.channels||[];const nextChannel=nextChannels.some((v:ChannelRow)=>v.id===preferredChannelId)?preferredChannelId:nextChannels[0]?.id||"";setChannels(nextChannels);setChannelId(nextChannel);setMembers(b.members||[]);setSelectedMembers((b.members||[]).filter((m:MemberRow)=>m.id!=="owner").map((m:MemberRow)=>m.id));if(nextChannel===preferredChannelId)setMessages(c.messages||[]);else if(nextChannel)await loadMessages(id,nextChannel);setError("")}).catch(()=>setError(u.retry)).finally(()=>{setLoadingGroup(false);setGroupDataReady(true);setMessagesReady(true)})};
 const loadFiles=(id:string)=>fetch(`/api/uploads?groupId=${encodeURIComponent(id)}`,{cache:"no-store"}).then(async r=>{if(!r.ok)throw new Error();const data=await r.json() as {files:FileRow[]};setFiles(data.files||[])}).catch(()=>setError(u.retry));
 const loadMessages=(gid:string,cid:string)=>fetch(`/api/messages?groupId=${encodeURIComponent(gid)}&channelId=${encodeURIComponent(cid)}`,{cache:"no-store"}).then(async r=>{if(!r.ok)throw new Error();const data=await r.json() as {messages:MessageRow[]};setMessages(data.messages||[])}).catch(()=>setError(t.groups.lock)).finally(()=>setMessagesReady(true));
 useEffect(()=>{loadGroups();fetch("/api/participant",{cache:"no-store"}).then(r=>r.json()).then(d=>setMe(d.participant?.id||"owner")).catch(()=>setMe("owner"))},[]);useEffect(()=>{if(!active||!groupId||!channelId)return;const refresh=()=>{if(document.visibilityState==="visible")loadMessages(groupId,channelId)};const timer=setInterval(refresh,7000);document.addEventListener("visibilitychange",refresh);return()=>{clearInterval(timer);document.removeEventListener("visibilitychange",refresh)}},[active,groupId,channelId]);
 async function send(){if(!draft.trim()||!groupId||!channelId)return;const res=await fetch("/api/messages",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({groupId,channelId,body:draft})}).catch(()=>null);if(res?.ok){setDraft("");await loadMessages(groupId,channelId)}else setError(u.retry)}
 async function createChannel(){if(!newChannel.trim())return;const r=await fetch("/api/channels",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({groupId,name:newChannel})});if(r.ok){setNewChannel("");await loadGroup(groupId,channelId)}}
 async function saveEdit(id:string){if(!editText.trim())return;const r=await fetch("/api/messages",{method:"PATCH",headers:{"content-type":"application/json"},body:JSON.stringify({id,body:editText})});if(r.ok){setEditing("");await loadMessages(groupId,channelId)}}
 async function removeMessage(id:string){if(!confirm(u.remove))return;const r=await fetch(`/api/messages?id=${encodeURIComponent(id)}`,{method:"DELETE"});if(r.ok)await loadMessages(groupId,channelId)}
 async function saveGroup(){setError("");const method=groupFormMode==="create"?"POST":"PATCH";const body=groupFormMode==="create"?{name:groupName,members:selectedMembers}:{id:groupId,name:groupName,members:selectedMembers};const r=await fetch("/api/groups",{method,headers:{"content-type":"application/json"},body:JSON.stringify(body)});if(r.ok){setShowGroupForm(false);setGroupName("");setSelectedMembers([]);await loadGroups();return}await r.json().catch(()=>({error:""}));setShowGroupForm(false);setError(u.retry)}
 async function deleteGroup(){if(!groupId||!confirm(u.remove))return;const r=await fetch(`/api/groups?id=${encodeURIComponent(groupId)}`,{method:"DELETE"});if(r.ok){setShowGroupForm(false);setGroupId("");await loadGroups()}}
 function openCreate(){setGroupFormMode("create");setGroupName("");setSelectedMembers([]);setShowGroupForm(true)}function openSettings(){if(!group)return;setGroupFormMode("settings");setGroupName(group.name);setSelectedMembers(members.filter(m=>m.id!=="owner").map(m=>m.id));setShowGroupForm(true)}
 const group=groups.find(x=>x.id===groupId);const channel=channels.find(x=>x.id===channelId);const onlineCutoff=now-5*60*1000;
 if(!groupsLoaded||(groups.length>0&&(!groupDataReady||!messagesReady)))return <div className="discordEmpty chatInitialLoading" role="status" aria-live="polite"><div><span className="chatLoadingMark" aria-hidden="true"/><p>{u.loading}</p></div></div>;
 if(!groups.length)return <div className="discordEmpty"><div><span className="emptyServerIcon">＋</span><h1>{u.createChat}</h1><p>{u.createHint}</p>{canCreate&&<button className="primary" onClick={openCreate}>{u.createChat}</button>}{error&&<small>{error}</small>}</div>{showGroupForm&&<GroupForm lang={lang} mode={groupFormMode} name={groupName} setName={setGroupName} participants={allParticipants} selected={selectedMembers} setSelected={setSelectedMembers} onSave={saveGroup} onClose={()=>setShowGroupForm(false)} onDelete={deleteGroup}/>}</div>;
 return <div className="communityPage"><div className="communityShell"><aside className="serverRail" aria-label={t.nav.groups}>{groups.map(g=><button key={g.id} className={g.id===groupId?"active":""} onClick={()=>{setGroupId(g.id);void loadGroup(g.id,g.default_channel_id||"")}} title={g.name}>{g.name.slice(0,2).toUpperCase()}</button>)}{canCreate&&<button className="addServer" onClick={openCreate} title={u.createChat}>＋</button>}</aside><aside className="channelRail"><header><b>{group?.name}</b><small>🔒 {t.nav.groups}</small></header><div className="channelTitle"><span>{u.privateChannel}</span>{group?.can_manage&&<button onClick={openSettings}>⚙</button>}</div>{channels.map(c=><button key={c.id} className={!showFiles&&c.id===channelId?"active":""} onClick={()=>{setMessagesReady(false);setMessages([]);setChannelId(c.id);setShowFiles(false);void loadMessages(groupId,c.id)}}><span>#</span>{c.name}</button>)}<button className={showFiles?"active":""} onClick={()=>{setShowFiles(true);void loadFiles(groupId)}}><span>▣</span>{u.files}</button>{group?.can_manage&&<div className="newChannel"><input value={newChannel} onChange={e=>setNewChannel(e.target.value)} onKeyDown={e=>{if(e.key==="Enter")createChannel()}} placeholder={u.newChannel}/><button onClick={createChannel}>＋</button></div>}<footer><i className="onlineDot"/><div><b>{me==="owner"?"Huie Chen":members.find(x=>x.id===me)?.display_code||t.participant}</b><small>{u.online}</small></div></footer></aside><section className="conversation"><header><div><b>{showFiles?"▣":"#"} {showFiles?u.files:channel?.name}</b><small>{showFiles?u.sharedFiles:u.privateChannel}</small></div><span>{group?.member_count} {u.members} {canManage&&<button className="groupSettingsButton" onClick={openSettings}>⚙</button>}</span></header>{loadingGroup&&<div className="chatLoading"><span>{u.loading}</span><button onClick={()=>loadGroup(groupId,channelId)}>{u.retry}</button></div>}{showFiles?<div className="fileWorkspace"><LiveUpload t={t} lang={lang} groupId={groupId} onUploaded={()=>loadFiles(groupId)}/>{files.length?<GroupFileGallery files={files} lang={lang}/>:<div className="emptyChannel">{u.noFiles}</div>}</div>:<><div className="discordMessages">{messages.length?messages.map(m=>{const own=group?.can_manage||m.participant_id===me;return <article key={m.id}><div className="messageAvatar">{m.display_code.slice(-2)}</div><div className="messageBody"><header><b>{m.display_code}</b><time>{new Date(Number(m.created_at)).toLocaleString(lang)}{m.edited_at?` · ${u.edit}`:""}</time></header>{editing===m.id?<div className="editComposer"><input value={editText} onChange={e=>setEditText(e.target.value)} onKeyDown={e=>{if(e.key==="Enter")saveEdit(m.id)}}/><button onClick={()=>saveEdit(m.id)}>{u.save}</button><button onClick={()=>setEditing("")}>{u.cancel}</button></div>:<p>{m.body}</p>}</div>{own&&editing!==m.id&&<div className="messageActions"><button onClick={()=>{setEditing(m.id);setEditText(m.body)}}>{u.edit}</button><button onClick={()=>removeMessage(m.id)}>{u.remove}</button></div>}</article>}):<div className="emptyChannel"><b># {channel?.name}</b><p>{u.channelStart}</p></div>}</div><div className="discordComposer"><button onClick={()=>{setShowFiles(true);void loadFiles(groupId)}}>＋</button><textarea rows={1} value={draft} onChange={e=>setDraft(e.target.value)} onKeyDown={e=>{if(e.key==="Enter"&&!e.shiftKey){e.preventDefault();send()}}} placeholder={`${t.groups.placeholder} #${channel?.name||""}`}/><button onClick={send}>{t.groups.send}</button></div></>}</section><aside className="memberRail"><h3>{u.online} — {members.filter(m=>Number(m.last_active_at)>onlineCutoff).length}</h3>{members.filter(m=>Number(m.last_active_at)>onlineCutoff).map(m=><div key={m.id}><span className="memberAvatar">{m.display_code.slice(-2)}<i/></span><b>{m.display_code}</b></div>)}<h3>{u.offline} — {members.filter(m=>!m.last_active_at||Number(m.last_active_at)<=onlineCutoff).length}</h3>{members.filter(m=>!m.last_active_at||Number(m.last_active_at)<=onlineCutoff).map(m=><div className="offline" key={m.id}><span className="memberAvatar">{m.display_code.slice(-2)}</span><b>{m.display_code}</b></div>)}</aside></div>{showGroupForm&&<GroupForm lang={lang} mode={groupFormMode} name={groupName} setName={setGroupName} participants={allParticipants} selected={selectedMembers} setSelected={setSelectedMembers} onSave={saveGroup} onClose={()=>setShowGroupForm(false)} onDelete={deleteGroup}/>}</div>
}



function GroupForm({lang,mode,name,setName,participants,selected,setSelected,onSave,onClose,onDelete}:{lang:Language;mode:"create"|"settings";name:string;setName:(v:string)=>void;participants:ParticipantRow[];selected:string[];setSelected:(v:string[])=>void;onSave:()=>void;onClose:()=>void;onDelete:()=>void}){const u=uiCopy[lang];const t=translations[lang];return <div className="groupModal" role="dialog" aria-modal="true" aria-label={mode==="create"?u.createChat:u.settings}><div><header><div><span className="kicker">{mode==="create"?u.createChat:u.settings}</span><h2>{mode==="create"?u.createChat:u.settings}</h2></div><button onClick={onClose} aria-label={u.close}>×</button></header><label>{u.createChat}<input value={name} onChange={e=>setName(e.target.value)}/></label>{mode==="settings"&&<><span className="kicker">{u.members}</span><div className="modalMembers">{participants.length?participants.map(p=><label key={p.id}><input type="checkbox" checked={selected.includes(p.id)} onChange={()=>setSelected(selected.includes(p.id)?selected.filter(id=>id!==p.id):[...selected,p.id])}/><span>{p.display_code}</span></label>):<p>{u.noContent}</p>}</div></>}{mode==="create"&&<p className="groupCreateNote">{u.createHint}</p>}<footer>{mode==="settings"&&<button className="danger" onClick={onDelete}>{u.remove}</button>}<span/><button onClick={onClose}>{u.cancel}</button><button className="primary" disabled={!name.trim()} onClick={onSave}>{mode==="create"?u.createChat:u.save}</button></footer><small>{t.groups.lock}</small></div></div>}

export function GroupFileGallery({files,lang}:{files:FileRow[];lang:Language}){
 const u=uiCopy[lang];
 const [preview,setPreview]=useState<FileRow|null>(null);
 useEffect(()=>{if(!preview)return;const close=(event:KeyboardEvent)=>{if(event.key==="Escape")setPreview(null)};addEventListener("keydown",close);return()=>removeEventListener("keydown",close)},[preview]);
 return <><div className="groupFiles fileGallery">{files.map(file=>{const url=`/api/uploads?id=${encodeURIComponent(file.id)}`;const image=file.content_type.startsWith("image/")&&!/hei[cf]$/i.test(file.content_type);return image?<button className="imageFileCard" key={file.id} onClick={()=>setPreview(file)} aria-label={`${u.viewImage} ${file.name}`}><img src={url} alt={file.name} loading="lazy"/><span><b>{file.name}</b><small>{(Number(file.size)/1024/1024).toFixed(1)} MB</small></span></button>:<a className="documentFileCard" key={file.id} href={url} download={file.name}><b>{file.name}</b><small>{(Number(file.size)/1024/1024).toFixed(1)} MB · {u.download}</small></a>})}</div>{preview&&<div className="imageLightbox" role="dialog" aria-modal="true" aria-label={u.imagePreview}><button className="lightboxBackdrop" onClick={()=>setPreview(null)} aria-label={u.close}/><button className="lightboxClose" onClick={()=>setPreview(null)} aria-label={u.close}>× <span>{u.close}</span></button><figure><img src={`/api/uploads?id=${encodeURIComponent(preview.id)}`} alt={preview.name}/><figcaption>{preview.name}</figcaption></figure></div>}</>
}

export function WorkspaceFiles({t,lang,onJournal}:{t:Translation;lang:Language;onJournal:()=>void}){
 const zh=lang==="zh";const [week,setWeek]=useState<number|null>(null);const [openCategory,setOpenCategory]=useState<"draft"|"process"|"final"|null>(null);const [files,setFiles]=useState<Record<"draft"|"process"|"final",FileRow[]>>({draft:[],process:[],final:[]});const [loaded,setLoaded]=useState(false);
 const categories=[{id:"draft" as const,title:zh?"初稿":"Drafts",note:zh?"早期方案、草图、文字与尚未定稿的版本":"Early proposals, sketches, text, and unfinished versions"},{id:"process" as const,title:zh?"过程文件":"Work in progress",note:zh?"测试、迭代、中间版本及制作材料":"Tests, iterations, intermediate versions, and production material"},{id:"final" as const,title:zh?"成品文件":"Final works",note:zh?"确认完成、可供展示或交付的版本":"Approved files ready for presentation or delivery"}];
 const load=(selectedWeek:number)=>{setLoaded(false);return Promise.all(categories.map(c=>fetch(`/api/uploads?category=${c.id}&week=${selectedWeek}`,{cache:"no-store"}).then(r=>r.ok?r.json():{files:[]}))).then(rows=>{setFiles({draft:rows[0].files||[],process:rows[1].files||[],final:rows[2].files||[]});setLoaded(true)}).catch(()=>setLoaded(true))};useEffect(()=>{if(week!==null)load(week)},[week]);
 const enterWeek=(value:number)=>{setWeek(value);setOpenCategory(null)};const back=()=>{if(openCategory)setOpenCategory(null);else setWeek(null)};const current=openCategory?categories.find(c=>c.id===openCategory):null;
 return <div className="page workspaceFiles"><header className="workspaceFilesHead"><div><span className="kicker">{beijingGreeting(lang)} · BEIJING TIME</span><h1>{zh?"创作资料库":"Creative Library"}</h1><p>{zh?"按周次进入资料夹，再选择文件类别提交。所有内容会保留在对应周次中。":"Open a week, choose a file category, then submit. Everything remains filed under its project week."}</p></div>{week!==null&&<button className="libraryBack" onClick={back}>← {openCategory?(zh?`返回 Week ${week}`:`Back to Week ${week}`):(zh?"全部周次":"All weeks")}</button>}</header><nav className="libraryBreadcrumb" aria-label={zh?"资料库路径":"Library path"}><button onClick={()=>{setWeek(null);setOpenCategory(null)}}>{zh?"创作资料库":"Creative Library"}</button>{week!==null&&<><span>/</span><button onClick={()=>setOpenCategory(null)}>Week {week}</button></>}{current&&<><span>/</span><b>{current.title}</b></>}</nav>{week===null?<section className="libraryWeeks"><div className="librarySectionTitle"><span className="kicker">PROJECT WEEKS</span><h2>{zh?"选择周次":"Choose a week"}</h2></div><div>{[0,1,2,3,4].map((value)=><button className={`weekFolder week${value}`} key={value} onClick={()=>enterWeek(value)}><span>W{value}</span><div><b>Week {value}</b><small>{value===0?(zh?"开始前准备与项目资料":"Preparation and project materials"):(zh?"本周初稿、过程与成品":"Drafts, process and final work")}</small></div><i>→</i></button>)}</div></section>:openCategory&&current?<section className={`libraryCategoryDetail ${current.id}`}><header><div><span className="kicker">WEEK {week} · {current.id.toUpperCase()}</span><h2>{current.title}</h2><p>{current.note}</p></div><b>{files[current.id].length}</b></header><LiveUpload t={t} lang={lang} category={current.id} week={week} onUploaded={()=>load(week)}/>{loaded&&files[current.id].length?<GroupFileGallery files={files[current.id]} lang={lang}/>:<div className="workspaceEmpty">{zh?"这个资料夹目前为空。可以在这里提交文件。":"This folder is empty. Submit files here when ready."}</div>}</section>:<><section className="libraryCategories"><div className="librarySectionTitle"><span className="kicker">WEEK {week}</span><h2>{zh?"选择文件类别":"Choose a category"}</h2></div><div>{categories.map((category,index)=><button className={`categoryFolder ${category.id}`} key={category.id} onClick={()=>setOpenCategory(category.id)}><span>{String(index+1).padStart(2,"0")}</span><div><b>{category.title}</b><small>{category.note}</small></div><strong>{files[category.id].length}</strong><i>→</i></button>)}<button className="categoryFolder journal" onClick={onJournal}><span>04</span><div><b>{zh?"照片日志":"Photo journal"}</b><small>{zh?"记录创作现场、测试与过程照片":"Document the studio, testing, and process"}</small></div><i>→</i></button></div></section>{week===0&&<ProjectAnnouncement lang={lang}/>}</>}</div>
}

export function LiveLinks({t,lang}:{t:Translation;lang:Language}){
 const u=uiCopy[lang];const [links,setLinks]=useState<GameLinkRow[]>([]);const [loaded,setLoaded]=useState(false);
 useEffect(()=>{fetch("/api/game-links",{cache:"no-store"}).then(async r=>{if(r.ok){const d=await r.json() as {links:GameLinkRow[]};setLinks(d.links||[])}setLoaded(true)}).catch(()=>setLoaded(true))},[]);
 return <div className="page"><div className="kicker">{t.links.label}</div><h1>{t.links.title}</h1>{loaded&&!links.length?<div className="lock">{u.noContent}</div>:<div className="realList">{links.map((link,i)=><article key={link.id} className={i===0?"version":"historyCard"}><div><span className={i===0?"live":"kicker"}>{i===0?u.currentBuild:u.previousBuild}</span><h2>{link.version}</h2>{(lang==="zh"||lang==="en")&&<p>{(lang==="zh"?link.notes_zh:link.notes_en)||""}</p>}<small>{new Date(Number(link.published_at)).toLocaleDateString(lang)}</small></div><a className="primary" href={link.url} target="_blank" rel="noreferrer">{t.links.open} ↗</a></article>)}</div>}</div>
}

export function LiveJournal({t,lang}:{t:Translation;lang:Language}){
 const zh=lang==="zh",u=uiCopy[lang];
 const [entries,setEntries]=useState<JournalRow[]>([]),[loaded,setLoaded]=useState(false),[canEdit,setCanEdit]=useState(false),[filter,setFilter]=useState("all"),[editing,setEditing]=useState<JournalRow|null>(null);
 const [titleZh,setTitleZh]=useState(""),[titleEn,setTitleEn]=useState(""),[bodyZh,setBodyZh]=useState(""),[bodyEn,setBodyEn]=useState(""),[stage,setStage]=useState("week-0"),[tags,setTags]=useState(""),[occurredAt,setOccurredAt]=useState(()=>new Date().toISOString().slice(0,10)),[file,setFile]=useState<File|null>(null),[busy,setBusy]=useState(false),[status,setStatus]=useState("");
 const load=()=>fetch("/api/journal",{cache:"no-store"}).then(async r=>{if(r.ok){const d=await r.json() as {entries:JournalRow[];canEdit:boolean};setEntries(d.entries||[]);setCanEdit(Boolean(d.canEdit))}setLoaded(true)}).catch(()=>setLoaded(true));useEffect(()=>{load()},[]);
 const reset=()=>{setEditing(null);setTitleZh("");setTitleEn("");setBodyZh("");setBodyEn("");setStage("week-0");setTags("");setOccurredAt(new Date().toISOString().slice(0,10));setFile(null)};
 const beginEdit=(entry:JournalRow)=>{setEditing(entry);setTitleZh(entry.title_zh);setTitleEn(entry.title_en);setBodyZh(entry.body_zh||"");setBodyEn(entry.body_en||"");setStage(entry.stage||"week-0");setTags(entry.tags||"");setOccurredAt(new Date(Number(entry.occurred_at)).toISOString().slice(0,10));document.querySelector(".journalEditor")?.scrollIntoView({behavior:"smooth",block:"start"})};
 async function save(){if(!titleZh.trim()||(!editing&&!file))return;setBusy(true);setStatus("");let res:Response|null=null;if(editing){res=await fetch("/api/journal",{method:"PATCH",headers:{"content-type":"application/json"},body:JSON.stringify({id:editing.id,titleZh,titleEn:titleEn||titleZh,bodyZh,bodyEn:bodyEn||bodyZh,stage,tags,occurredAt:Date.parse(occurredAt)})}).catch(()=>null)}else{const form=new FormData();form.set("file",file!);form.set("titleZh",titleZh);form.set("titleEn",titleEn||titleZh);form.set("bodyZh",bodyZh);form.set("bodyEn",bodyEn||bodyZh);form.set("stage",stage);form.set("tags",tags);form.set("occurredAt",occurredAt);res=await fetch("/api/journal",{method:"POST",body:form}).catch(()=>null)}setBusy(false);if(res?.ok){setStatus(zh?"✓ 照片日志已保存":"✓ Photo journal entry saved");reset();await load()}else setStatus(shortError(lang))}
 async function remove(entry:JournalRow){if(!confirm(zh?`删除“${entry.title_zh}”？此操作无法撤销。`:`Delete “${entry.title_en}”? This cannot be undone.`))return;const res=await fetch(`/api/journal?id=${encodeURIComponent(entry.id)}`,{method:"DELETE"}).catch(()=>null);if(res?.ok){setStatus(zh?"日志已删除。":"Journal entry deleted.");await load()}else setStatus(shortError(lang))}
 const entryTitle=(entry:JournalRow)=>zh?entry.title_zh:entry.title_en||entry.title_zh;
 const entryBody=(entry:JournalRow)=>zh?entry.body_zh:entry.body_en||entry.body_zh;
 const filtered=filter==="all"?entries:entries.filter(entry=>entry.stage===filter);
 return <div className="page productionJournal"><header className="journalHero"><div><span className="kicker">PRODUCTION PHOTO JOURNAL</span><h1>{zh?"制作照片日志":"Production Photo Journal"}</h1><p>{zh?"按项目阶段记录讨论、测试、制作现场与关键决策。日志由主策划维护，所有创作者均可阅读。":"A stage-by-stage record of discussions, playtests, production sessions, and key decisions. Maintained by the Lead Designer and visible to every creator."}</p></div><strong>{String(entries.length).padStart(2,"0")}</strong></header><nav className="journalFilters" aria-label={zh?"按阶段筛选":"Filter by stage"}>{["all","week-0","week-1","week-2","week-3","week-4"].map(value=><button key={value} className={filter===value?"active":""} onClick={()=>setFilter(value)}>{value==="all"?(zh?"全部":"All"):value.replace("week-","Week ")}<small>{value==="all"?entries.length:entries.filter(entry=>entry.stage===value).length}</small></button>)}</nav>{loaded&&!filtered.length?<div className="journalEmpty"><b>{zh?"这一阶段还没有日志":"No journal entries for this stage"}</b><p>{canEdit?(zh?"发布第一条制作记录后会显示在这里。":"Publish the first production record to begin the journal."):(zh?"主策划发布后，所有创作者都会在这里看到。":"Entries will appear here when the Lead Designer publishes them.")}</p></div>:<section className="journalTimeline">{filtered.map((entry,index)=><article key={entry.id} className="productionEntry"><div className="journalIndex"><span>{String(index+1).padStart(2,"0")}</span><i/></div><figure><img src={`/api/journal?id=${encodeURIComponent(entry.id)}`} alt={entryTitle(entry)} loading="lazy"/><figcaption>{entry.file_name}</figcaption></figure><div className="journalStory"><div className="journalMeta"><span>{entry.stage.replace("week-","WEEK ")}</span><time>{new Date(Number(entry.occurred_at)).toLocaleDateString(zh?"zh-CN":"en-GB",{year:"numeric",month:"short",day:"numeric",timeZone:"Asia/Shanghai"})}</time></div><h2>{entryTitle(entry)}</h2>{entryBody(entry)&&<p>{entryBody(entry)}</p>}{entry.tags&&<div className="journalTags">{entry.tags.split(/[,，]/).map(tag=>tag.trim()).filter(Boolean).map(tag=><span key={tag}>{tag}</span>)}</div>}{canEdit&&<div className="journalEntryActions"><button onClick={()=>beginEdit(entry)}>{zh?"编辑记录":"Edit"}</button><button className="danger" onClick={()=>remove(entry)}>{zh?"删除":"Delete"}</button></div>}</div></article>)}</section>}{canEdit&&<section className="journalEditor"><header><div><span className="kicker">{editing?"EDIT ENTRY":"NEW ENTRY"}</span><h2>{editing?(zh?"编辑制作记录":"Edit production entry"):(zh?"发布制作记录":"Publish production entry")}</h2></div>{editing&&<button onClick={reset}>{zh?"取消编辑":"Cancel"}</button>}</header><div className="journalEditorGrid"><label>{zh?"中文标题":"Chinese title"}<input value={titleZh} onChange={e=>setTitleZh(e.target.value)} placeholder={u.photoTitle}/></label><label>{zh?"英文标题（可选）":"English title (optional)"}<input value={titleEn} onChange={e=>setTitleEn(e.target.value)}/></label><label className="wide">{zh?"中文记录":"Chinese notes"}<textarea value={bodyZh} onChange={e=>setBodyZh(e.target.value)} placeholder={zh?"记录现场、测试结果、变化与下一步":"Record the session, test result, changes, and next step"}/></label><label className="wide">{zh?"英文记录（可选）":"English notes (optional)"}<textarea value={bodyEn} onChange={e=>setBodyEn(e.target.value)}/></label><label>{zh?"项目阶段":"Project stage"}<select value={stage} onChange={e=>setStage(e.target.value)}>{[0,1,2,3,4].map(week=><option value={`week-${week}`} key={week}>Week {week}</option>)}</select></label><label>{zh?"记录日期":"Entry date"}<input type="date" value={occurredAt} onChange={e=>setOccurredAt(e.target.value)}/></label><label className="wide">{zh?"标签（逗号分隔）":"Tags (comma separated)"}<input value={tags} onChange={e=>setTags(e.target.value)} placeholder={zh?"例如：玩法测试，视觉开发，团队讨论":"e.g. playtest, visual development, team discussion"}/></label>{!editing&&<label className="wide journalImageField">{zh?"现场照片":"Production image"}<input type="file" accept="image/jpeg,image/png,image/webp,image/heic,image/heif" onChange={e=>setFile(e.target.files?.[0]||null)}/><span>{file?.name||u.choosePhoto}</span></label>}</div><footer><small>{zh?"只有主策划可以发布与编辑；所有创作者均可阅读。":"Only the Lead Designer can publish and edit; every creator can read."}</small><button className="dark" disabled={busy||!titleZh.trim()||(!editing&&!file)} onClick={save}>{busy?u.uploading:(editing?(zh?"保存修改":"Save changes"):(zh?"发布日志":"Publish entry"))}</button></footer></section>}{status&&<p className="saveStatus" role="status">{status}</p>}</div>
}

export function OwnerContentManager({lang}:{lang:Language}){
 const [taskWeek,setTaskWeek]=useState(0);
 const zh=lang==="zh";const [tasks,setTasks]=useState<TaskRow[]>([]);const [forms,setForms]=useState<SurveyFormRow[]>([]);const [links,setLinks]=useState<GameLinkRow[]>([]);const [taskZh,setTaskZh]=useState("");const [taskEn,setTaskEn]=useState("");const [surveyTitle,setSurveyTitle]=useState("");const [surveyQuestion,setSurveyQuestion]=useState("");const [version,setVersion]=useState("");const [url,setUrl]=useState("");const [notes,setNotes]=useState("");const [status,setStatus]=useState("");
 const load=()=>Promise.all([fetch("/api/tasks",{cache:"no-store"}).then(r=>r.json()),fetch("/api/surveys?manage=1",{cache:"no-store"}).then(r=>r.json()),fetch("/api/game-links",{cache:"no-store"}).then(r=>r.json())]).then(([a,b,c])=>{setTasks(a.tasks||[]);setForms(b.forms||[]);setLinks(c.links||[])}).catch(()=>setStatus(zh?"内容管理暂时无法读取。":"Content management is temporarily unavailable."));useEffect(()=>{load()},[]);
 async function createTask(){const r=await fetch("/api/tasks",{method:"PUT",headers:{"content-type":"application/json"},body:JSON.stringify({titleZh:taskZh,titleEn:taskEn||taskZh,week:taskWeek})});if(r.ok){setTaskZh("");setTaskEn("");setStatus(zh?`Week ${taskWeek} 任务已发布。`:`Week ${taskWeek} task published.`);await load()}}
 async function toggleTask(id:string,current:string){await fetch("/api/tasks",{method:"PATCH",headers:{"content-type":"application/json"},body:JSON.stringify({id,status:current==="archived"?"active":"archived"})});await load()}
 async function createSurvey(){const r=await fetch("/api/surveys",{method:"PUT",headers:{"content-type":"application/json"},body:JSON.stringify({titleZh:surveyTitle,titleEn:surveyTitle,questionZh:surveyQuestion,questionEn:surveyQuestion})});if(r.ok){setSurveyTitle("");setSurveyQuestion("");setStatus(zh?"问卷已发布，上一份已归档。":"Survey published; the previous one was archived.");await load()}}
 async function createLink(){const r=await fetch("/api/game-links",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({version,url,notesZh:notes,notesEn:notes})});if(r.ok){setVersion("");setUrl("");setNotes("");setStatus(zh?"版本链接已发布。":"Build link published.");await load()}else setStatus(zh?"请填写有效的网址和版本名称。":"Enter a valid URL and version name.")}
 return <section className="contentManager"><div className="contentEditorHead"><div><span className="kicker">REAL CONTENT</span><h2>{zh?"项目功能内容":"Project content"}</h2><p>{zh?"参与端只显示你在这里真实发布的内容。":"Participants only see content you publish here."}</p></div></div><div className="manageGrid"><div className="opsCard"><h3>{zh?"任务":"Tasks"}</h3><select value={taskWeek} onChange={e=>setTaskWeek(Number(e.target.value))}>{[0,1,2,3,4].map(n=><option key={n} value={n}>Week {n}</option>)}</select><input value={taskZh} onChange={e=>setTaskZh(e.target.value)} placeholder={zh?"任务标题":"Task title"}/><input value={taskEn} onChange={e=>setTaskEn(e.target.value)} placeholder={zh?"英文标题（可选）":"English title (optional)"}/><button className="dark" disabled={!taskZh.trim()} onClick={createTask}>{zh?"发布任务":"Publish task"}</button><div className="miniList">{tasks.map(x=><div key={x.id}><span><b>{x.title_zh}</b><small>Week {x.week} · {x.status}</small></span><button onClick={()=>toggleTask(x.id,x.status)}>{x.status==="archived"?(zh?"恢复":"Restore"):(zh?"归档":"Archive")}</button></div>)}</div></div><div className="opsCard"><h3>{zh?"问卷":"Survey"}</h3><input value={surveyTitle} onChange={e=>setSurveyTitle(e.target.value)} placeholder={zh?"问卷标题":"Survey title"}/><textarea value={surveyQuestion} onChange={e=>setSurveyQuestion(e.target.value)} placeholder={zh?"开放问题":"Open question"}/><button className="dark" disabled={!surveyTitle.trim()||!surveyQuestion.trim()} onClick={createSurvey}>{zh?"发布问卷":"Publish survey"}</button><small>{forms.filter(x=>x.status==="active").length?zh?"当前有一份开放问卷。":"One survey is active.":zh?"暂无开放问卷。":"No active survey."}</small></div><div className="opsCard"><h3>{zh?"游戏版本链接":"Game build links"}</h3><input value={version} onChange={e=>setVersion(e.target.value)} placeholder={zh?"版本名称":"Version name"}/><input value={url} onChange={e=>setUrl(e.target.value)} placeholder="https://"/><textarea value={notes} onChange={e=>setNotes(e.target.value)} placeholder={zh?"版本说明（可选）":"Build notes (optional)"}/><button className="dark" disabled={!version.trim()||!url.trim()} onClick={createLink}>{zh?"发布链接":"Publish link"}</button><small>{zh?`已发布 ${links.length} 个真实链接。`:`${links.length} real link(s) published.`}</small></div></div>{status&&<p className="saveStatus" role="status">{status}</p>}</section>
}

type InvitationRow={id:string;label:string;token_hint:string;display_code:string;participant_id:string;created_at:number;expires_at:number|null;revoked_at:number|null};
export function OwnerOperations({lang,participants,onParticipantsChanged}:{lang:Language;participants:ParticipantRow[];onParticipantsChanged:()=>void}){
 const zh=lang==="zh";const [invitations,setInvitations]=useState<InvitationRow[]>([]);const [label,setLabel]=useState("");const [newToken,setNewToken]=useState("");const [groupName,setGroupName]=useState("");const [members,setMembers]=useState<string[]>([]);const [groups,setGroups]=useState<GroupRow[]>([]);const [status,setStatus]=useState("");
 const load=()=>Promise.all([fetch("/api/invitations",{cache:"no-store"}).then(r=>r.json()),fetch("/api/groups",{cache:"no-store"}).then(r=>r.json())]).then(([a,b])=>{setInvitations(a.invitations||[]);setGroups(b.groups||[])}).catch(()=>setStatus(zh?"管理数据暂时无法读取。":"Management data is temporarily unavailable."));
 useEffect(()=>{load()},[]);
 async function createInvite(){const res=await fetch("/api/invitations",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({label:label||undefined,expiresInDays:90})});const data=await res.json();if(res.ok){setNewToken(data.invitation.token);setLabel("");setStatus(zh?"邀请已创建；完整代码只在这里显示一次。":"Invitation created; the full code is shown only once.");await load();onParticipantsChanged()}}
 async function revoke(id:string){await fetch("/api/invitations",{method:"PATCH",headers:{"content-type":"application/json"},body:JSON.stringify({id})});await load()}
 async function copyInvite(){if(!newToken)return;const link=`${location.origin}/?invite=${encodeURIComponent(newToken)}`;const ok=await copyText(link);setStatus(ok?(zh?"邀请链接已复制。":"Invitation link copied."):(zh?"复制失败，请长按上面的邀请码手动拼接链接：":"Copy failed — long-press the code above and build the link manually:"))}
 async function createGroup(){setStatus("");const res=await fetch("/api/groups",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({name:groupName,members})});if(res.ok){setGroupName("");setMembers([]);setStatus(zh?"私密小组已建立。":"Private group created.");await load();return}const data=await res.json().catch(()=>({error:""})) as {error?:string};setStatus(zh?`建立失败：${data.error||"请重新登录 Owner 后再试。"}`:`Creation failed: ${data.error||"Sign in as the Owner and try again."}`)}
 const activeInvites=useMemo(()=>invitations.filter(x=>!x.revoked_at),[invitations]);
 return <section className="ownerOperations"><div className="opsGrid"><div className="opsCard"><span className="kicker">INVITATIONS</span><h2>{zh?"真实邀请管理":"Invitation management"}</h2><div className="inlineForm"><input value={label} onChange={e=>setLabel(e.target.value)} placeholder={zh?"邀请备注（可选）":"Invitation label (optional)"}/><button className="dark" onClick={createInvite}>{zh?"生成邀请":"Create invitation"}</button></div>{newToken&&<div className="tokenReveal"><code>{newToken}</code><button onClick={copyInvite}>{zh?"复制邀请链接":"Copy invitation link"}</button></div>}<div className="miniList">{activeInvites.slice(0,8).map(x=><div key={x.id}><span><b>{x.display_code}</b><small>{x.label||x.token_hint}</small></span><button onClick={()=>revoke(x.id)}>{zh?"撤销":"Revoke"}</button></div>)}</div></div><div className="opsCard"><span className="kicker">PRIVATE GROUPS</span><h2>{zh?"建立私密小组":"Create a private group"}</h2><input value={groupName} onChange={e=>setGroupName(e.target.value)} placeholder={zh?"小组名称":"Group name"}/><div className="memberPicker">{participants.slice(0,30).map(p=><label key={p.id}><input type="checkbox" checked={members.includes(p.id)} onChange={()=>setMembers(x=>x.includes(p.id)?x.filter(id=>id!==p.id):[...x,p.id])}/>{p.display_code}</label>)}</div><button className="dark" onClick={createGroup} disabled={!groupName||!members.length}>{zh?"建立小组":"Create group"}</button><small>{zh?`已有 ${groups.length} 个私密小组。只有 Owner 可以建立。`:`${groups.length} private group(s). Only the Owner can create them.`}</small></div></div>{status&&<p className="saveStatus" role="status">{status}</p>}</section>
}
